Section ALL.
  Variables (sp0 brk0 mbase : word) (rdraw : EntryDraw) (inp : ProcInput) (c : config).
  Hypothesis P : P_main sp0 brk0 mbase rdraw inp c.

  (* [comment removed for export] *)
  Theorem P_main_all : exists X,
      PM sp0 brk0 inp X c
   /\ pm_syms_ok (bv_unsigned sp0) (bv_unsigned brk0) 0 X
   /\ lzok BSEGS2 (zz2ww (PM_LAZY (bv_unsigned sp0) X)) (zz2ww (PM_S (bv_unsigned sp0) (bv_unsigned brk0) X)) (zz2ww (PM_ZR (bv_unsigned sp0) X)) c
   /\ pages_total (zz2ww (PM_S (bv_unsigned sp0) (bv_unsigned brk0) X)) <= PM_S_PAGES
   /\ PMC sp0 rdraw inp (bv_unsigned brk0) X (ms_mem (cfg_ms c)).
  Proof.
    pose proof P as P'. destruct P' as [(Vsp & Vbrk & Vmb & Vav & Vev & Vfit & Vuid & Vhw) (h & ch & E & R & FULL & model & Hh & _ & Hc & HC)].
    exists (Xof (hole_granted h) E). rewrite Hc.
    split; [exact (PM_open sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Hh HC)|].
    split; [exact (pm_syms_ok_open sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Hh HC)|].
    pose proof (lzok_open sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Hh HC) as [L1 L2].
    split; [exact L1|]. split; [exact L2|].
    cbn [cfg_ms cfg_of mkst ms_mem]. exact (PMC_open sp0 brk0 rdraw inp h ch E R FULL model Vsp Vbrk Vav Vev Vfit Hh HC).
  Qed.
End ALL.
